'use client';
import{jsx as _jsx}from"react/jsx-runtime";
import{useContext}from'react';
import{SegmentedControlContext}from'../SegmentedControl/SegmentedControl.js';
export function SegmentedControlItem({value,children}){
const control=useContext(SegmentedControlContext);
const picked=control?.value===value;
return(_jsx("button",{type:"button","aria-pressed":picked,"data-picked":picked,onClick:()=>control?.onSelect?.(value),className:"cieo cieo-segmented-control-item",children:children}));
}
